template.query:
query ExportImportSchema($includeData: Boolean = true, $includeRelations: Boolean = true, $format: String = "json", $compression: Boolean = false) {
  exportAllTables(
    options: {
      includeData: $includeData
      includeRelations: $includeRelations
      format: $format
      compression: $compression
    }
  ) {
    metadata {
      exportedAt
      version
      source
      options
      checksum
    }
    tables {
      id
      identifier
      description
      metadata
      createdAt
      updatedAt
      attributes {
        id
        identifier
        name
        description
        attributeType {
          id
          identifier
          name
          dataType
          allowedValues
          constraints
        }
        isRequired
        defaultValue
        createdAt
        updatedAt
      }
      statistics {
        nodeCount
        attributeCount
        relationCount
      }
    }
    globalRelationTypes {
      id
      identifier
      name
      description
      metadata
      createdAt
      updatedAt
    }
    globalAttributeTypes {
      id
      identifier
      name
      description
      dataType
      allowedValues
      constraints
      createdAt
      updatedAt
    }
    statistics {
      totalTables
      totalNodes
      totalRelations
      totalAttributes
      exportSize
    }
  }
}
